"use client";

import { useState, type ComponentProps, type ReactNode } from "react";

import { IconLayout } from "@rhs-ui/icons";
import { DisplayOptionsPanel } from "@rhs-ui/application/display-options-popover/panel";
import {
  changedSections,
  DEFAULT_LABELS,
  defaultDisplay,
  fill,
  readDisplay,
  type DisplayField,
  type DisplayLayout,
  type DisplayOptions,
  type DisplayOptionsLabels,
  type DisplayProperty,
  type DisplayValue,
} from "@rhs-ui/application/display-options-popover/options";
import { Badge } from "@rhs-ui/primitives/badge";
import { Button } from "@rhs-ui/primitives/button";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type {
  DisplayDirection,
  DisplayField,
  DisplayLayout,
  DisplayOptionsLabels,
  DisplayProperty,
  DisplaySection,
  DisplayValue,
} from "@rhs-ui/application/display-options-popover/options";
export { DisplayOptionsPanel, type DisplayOptionsPanelProps } from "@rhs-ui/application/display-options-popover/panel";

export interface DisplayOptionsPopoverProps extends Omit<ComponentProps<"div">, "children" | "defaultValue" | "onChange" | "onReset"> {
  /** The ways to lay the list out, as small icon tiles: an id, a label and, if you like, an icon element. */
  layouts: readonly DisplayLayout[];
  /** What the rows can be grouped by. Include an entry that means none, such as "No grouping". */
  groupings: readonly DisplayField[];
  /** What the rows can be ordered by. */
  orderings: readonly DisplayField[];
  /** The fields of a row that can be shown or hidden, each with whether it shows in the defaults. */
  properties: readonly DisplayProperty[];
  /** What is chosen, when you control the popover. Pair it with `onValueChange`. */
  value?: DisplayValue;
  /** What is chosen to begin with, when the popover keeps it itself. Default: the defaults. */
  defaultValue?: DisplayValue;
  /** What counts as unchanged, and what Reset returns to. Default: the first layout, grouping and ordering, ascending, and the properties that are not marked hidden. */
  defaults?: DisplayValue;
  /** Something was changed. It receives the whole value, and applies at once: this is a view setting, not a form. */
  onValueChange?: (next: DisplayValue) => void;
  /** Reset was pressed, after `onValueChange` received the defaults. */
  onReset?: () => void;
  /** Replaces the button. One element that takes a ref and props, such as a `Button`. */
  trigger?: ReactNode;
  /** Which edge of the button the panel lines up with. Default "end". */
  align?: "start" | "center" | "end";
  /** Whether the panel is open, when you control it. */
  open?: boolean;
  /** Whether the panel is open to begin with. */
  defaultOpen?: boolean;
  /** Called when the panel opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The words the button and the panel say, for translation. */
  labels?: DisplayOptionsLabels;
}

/**
 * The Display button of a list view: choose how rows are laid out, grouped and ordered, and which properties show on them.
 * Everything applies at once, because this is a view setting and not a form, and the button says how many of the four
 * settings differ from the defaults ("Display, 2 changed"). Layout is a small icon tile group, grouping and ordering use the
 * house select with a button that turns the ordering round, and properties are chips that show and hide fields. Reset puts
 * it all back and says so politely. The panel keeps inside the window and scrolls inside itself at 320 pixels.
 */
export function DisplayOptionsPopover({
  layouts,
  groupings,
  orderings,
  properties,
  value,
  defaultValue,
  defaults,
  onValueChange,
  onReset,
  trigger,
  align = "end",
  open,
  defaultOpen = false,
  onOpenChange,
  labels,
  className,
  ...props
}: DisplayOptionsPopoverProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const options: DisplayOptions = { layouts, groupings, orderings, properties };
  const base = defaults ?? defaultDisplay(options);
  const [own, setOwn] = useState<DisplayValue | undefined>(defaultValue);
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const isOpen = open ?? ownOpen;
  // A panel that is open from the start (a preview, a first-run tip) never takes focus from the page: that is only for a panel somebody opened.
  const [wasOpen, setWasOpen] = useState(isOpen);
  const [fresh, setFresh] = useState(isOpen);
  if (isOpen !== wasOpen) {
    setWasOpen(isOpen);
    if (!isOpen) setFresh(false);
  }
  const current = readDisplay(value ?? own, options, base);
  const count = changedSections(current, base).length;

  function setOpen(next: boolean) {
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  }

  return (
    <div data-slot="display-options-popover" data-changed={count || undefined} className={cn("inline-flex max-w-full min-w-0", className)} {...props}>
      <Popover open={isOpen} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          {trigger ?? (
            <Button type="button" variant="outline" className="gap-2">
              <IconLayout aria-hidden="true" />
              {words.trigger}
              {count > 0 ? (
                <Badge aria-hidden="true" className="-me-1 h-5 min-w-5 justify-center px-1.5 tabular-nums">
                  {count}
                </Badge>
              ) : null}
              {count > 0 ? <span className="sr-only">, {fill(words.changed, { count })}</span> : null}
            </Button>
          )}
        </PopoverTrigger>
        <PopoverContent
          align={align}
          collisionPadding={8}
          aria-label={words.title}
          onOpenAutoFocus={(event) => {
            // Radix would focus the first thing it finds, the Reset button in the header, and one press of Enter would put everything back: start on the layout instead.
            event.preventDefault();
            if (fresh) return;
            const panel = event.currentTarget;
            const first = panel instanceof HTMLElement ? panel.querySelector<HTMLElement>("[data-slot='toggle-group-item'][data-state='on']") : null;
            first?.focus({ preventScroll: true });
          }}
          className="flex max-h-[min(36rem,var(--radix-popover-content-available-height))] w-[min(21rem,calc(100vw-1rem))] flex-col overflow-hidden p-0"
        >
          <DisplayOptionsPanel
            layouts={layouts}
            groupings={groupings}
            orderings={orderings}
            properties={properties}
            value={current}
            defaults={base}
            onValueChange={(next) => {
              if (value === undefined) setOwn(next);
              onValueChange?.(next);
            }}
            onReset={onReset}
            labels={labels}
            className="min-h-0 flex-1"
          />
        </PopoverContent>
      </Popover>
    </div>
  );
}

"use client";

import { useEffect, useId, useState, type ComponentProps, type ReactNode } from "react";

import { IconArrowDown, IconArrowUp, IconBoard, IconCalendar, IconCheck, IconGrid, IconLayout, IconList, IconTable } from "@rhs-ui/icons";
import {
  changedSections,
  DEFAULT_LABELS,
  defaultDisplay,
  readDisplay,
  type DisplayField,
  type DisplayLayout,
  type DisplayOptions,
  type DisplayOptionsLabels,
  type DisplayProperty,
  type DisplaySection,
  type DisplayValue,
} from "@rhs-ui/application/display-options-popover/options";
import { Button } from "@rhs-ui/primitives/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@rhs-ui/primitives/select";
import { Toggle } from "@rhs-ui/primitives/toggle";
import { ToggleGroup, ToggleGroupItem } from "@rhs-ui/primitives/toggle-group";
import { cn } from "@/lib/utils";

export interface DisplayOptionsPanelProps extends Omit<ComponentProps<"div">, "children" | "defaultValue" | "onChange" | "onReset"> {
  /** The ways to lay the list out, as small icon tiles: an id, a label and, if you like, an icon element. */
  layouts: readonly DisplayLayout[];
  /** What the rows can be grouped by. Include an entry that means none, such as "No grouping". */
  groupings: readonly DisplayField[];
  /** What the rows can be ordered by. */
  orderings: readonly DisplayField[];
  /** The fields of a row that can be shown or hidden, each with whether it shows in the defaults. */
  properties: readonly DisplayProperty[];
  /** What is chosen, when you control the panel. Pair it with `onValueChange`. */
  value?: DisplayValue;
  /** What is chosen to begin with, when the panel keeps it itself. Default: the defaults. */
  defaultValue?: DisplayValue;
  /** What counts as unchanged, and what Reset returns to. Default: the first layout, grouping and ordering, ascending, and the properties that are not marked hidden. */
  defaults?: DisplayValue;
  /** Something was changed. It receives the whole value, and applies at once: this is a view setting, not a form. */
  onValueChange?: (next: DisplayValue) => void;
  /** Reset was pressed, after `onValueChange` received the defaults. */
  onReset?: () => void;
  /** The words the panel says, for translation. */
  labels?: DisplayOptionsLabels;
}

/** What a layout draws when you give it no icon: a drawing chosen from its id. */
const LAYOUT_ICONS: Record<string, ReactNode> = {
  list: <IconList />,
  board: <IconBoard />,
  table: <IconTable />,
  grid: <IconGrid />,
  gallery: <IconGrid />,
  cards: <IconGrid />,
  calendar: <IconCalendar />,
};

function Section({ id, title, aside, children }: { id: string; title: string; aside?: string; children: ReactNode }) {
  return (
    <div className="grid gap-2">
      <div className="flex items-baseline justify-between gap-3">
        <p id={id} className="text-xs font-medium text-muted-foreground">
          {title}
        </p>
        {aside ? <span className="text-[0.6875rem] text-muted-foreground">{aside}</span> : null}
      </div>
      {children}
    </div>
  );
}

/**
 * The inside of the display popover, on its own, for a sheet on a phone: the layout as small icon tiles, grouping and
 * ordering in the house select (with a button that turns the ordering round), and the properties as chips that show and hide
 * fields on every row. Everything applies the moment it is touched, because this is a view setting and not a form. A heading
 * whose setting differs from the defaults says so, and Reset puts everything back and says it politely.
 */
export function DisplayOptionsPanel({
  layouts,
  groupings,
  orderings,
  properties,
  value,
  defaultValue,
  defaults,
  onValueChange,
  onReset,
  labels,
  className,
  ...props
}: DisplayOptionsPanelProps) {
  const words: Required<DisplayOptionsLabels> = { ...DEFAULT_LABELS, ...labels };
  const id = useId();
  const options: DisplayOptions = { layouts, groupings, orderings, properties };
  const base = defaults ?? defaultDisplay(options);
  const [own, setOwn] = useState<DisplayValue | undefined>(defaultValue);
  const current = readDisplay(value ?? own, options, base);
  const changed = changedSections(current, base);
  const [said, setSaid] = useState("");
  const [restored, setRestored] = useState(false);
  const shown = new Set(current.properties);
  const tag = (section: DisplaySection) => (changed.includes(section) ? words.changedTag : undefined);

  // The visible "Back to the defaults" goes by itself after a moment; the live region keeps the words until the next change.
  useEffect(() => {
    if (!restored) return;
    const timer = window.setTimeout(() => setRestored(false), 2600);
    return () => window.clearTimeout(timer);
  }, [restored]);

  function apply(next: DisplayValue) {
    if (value === undefined) setOwn(next);
    // Cleared on the way in, so the same words are read out again after the next Reset.
    setSaid("");
    setRestored(false);
    onValueChange?.(next);
  }

  function reset() {
    if (changed.length === 0) return;
    if (value === undefined) setOwn(base);
    onValueChange?.(base);
    onReset?.();
    setSaid(words.resetDone);
    setRestored(true);
  }

  function toggleProperty(propertyId: string, on: boolean) {
    const next = new Set(current.properties);
    if (on) next.add(propertyId);
    else next.delete(propertyId);
    apply({ ...current, properties: properties.filter((property) => next.has(property.id)).map((property) => property.id) });
  }

  return (
    <div data-slot="display-options-panel" className={cn("flex min-h-0 flex-col bg-popover text-popover-foreground", className)} {...props}>
      <div className="flex shrink-0 items-center justify-between gap-3 border-b border-border py-2 pr-2.5 pl-4">
        <h2 className="text-sm font-semibold tracking-[-0.01em]">{words.title}</h2>
        <div className="flex items-center gap-1.5">
          {restored ? (
            <span aria-hidden="true" className="inline-flex items-center gap-1 text-xs text-muted-foreground">
              <IconCheck className="size-3.5" />
              {words.resetDone}
            </span>
          ) : null}
          {/* Not `disabled`: pressing Reset turns it off, and a disabled button would drop the focus it has. */}
          <Button
            type="button"
            variant="ghost"
            size="sm"
            aria-disabled={changed.length === 0 || undefined}
            onClick={reset}
            className="text-muted-foreground hover:text-foreground aria-disabled:pointer-events-none aria-disabled:opacity-50"
          >
            {words.reset}
          </Button>
        </div>
      </div>

      <div data-slot="display-options-body" className="relative min-h-0 flex-1 overflow-y-auto overscroll-contain [scrollbar-width:thin]">
        <div className="grid gap-5 p-4">
          <Section id={`${id}-layout`} title={words.layout} aside={tag("layout")}>
            <ToggleGroup
              type="single"
              variant="outline"
              value={current.layout}
              aria-labelledby={`${id}-layout`}
              // Pressing the tile that is already chosen would unchoose it: a layout is always one of the layouts.
              onValueChange={(next) => {
                if (next) apply({ ...current, layout: next });
              }}
              className="flex w-full"
            >
              {layouts.map((layout) => (
                <ToggleGroupItem
                  key={layout.id}
                  value={layout.id}
                  className="h-auto min-w-0 flex-1 flex-col gap-1.5 px-1 py-2.5 text-xs data-[state=on]:bg-muted data-[state=on]:text-foreground [&_svg:not([class*='size-'])]:size-5"
                >
                  {layout.icon ?? LAYOUT_ICONS[layout.id] ?? <IconLayout />}
                  <span className="max-w-full truncate">{layout.label}</span>
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
          </Section>

          <Section id={`${id}-grouping`} title={words.grouping} aside={tag("grouping")}>
            <Select value={current.grouping} onValueChange={(next) => apply({ ...current, grouping: next })}>
              <SelectTrigger size="sm" aria-labelledby={`${id}-grouping`} className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {groupings.map((field) => (
                  <SelectItem key={field.id} value={field.id} className="py-1.5">
                    {field.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Section>

          <Section id={`${id}-ordering`} title={words.ordering} aside={tag("ordering")}>
            <div className="flex items-center gap-2">
              <div className="min-w-0 flex-1">
                <Select value={current.ordering} onValueChange={(next) => apply({ ...current, ordering: next })}>
                  <SelectTrigger size="sm" aria-labelledby={`${id}-ordering`} className="w-full">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {orderings.map((field) => (
                      <SelectItem key={field.id} value={field.id} className="py-1.5">
                        {field.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <Toggle
                variant="outline"
                size="sm"
                pressed={current.direction === "desc"}
                onPressedChange={(on) => apply({ ...current, direction: on ? "desc" : "asc" })}
                aria-label={words.descending}
                title={words.descending}
                className="size-8 shrink-0 px-0 data-[state=on]:bg-muted data-[state=on]:text-foreground"
              >
                {current.direction === "desc" ? <IconArrowDown /> : <IconArrowUp />}
              </Toggle>
            </div>
          </Section>

          <Section id={`${id}-properties`} title={words.properties} aside={tag("properties") ?? words.propertiesHint}>
            <div role="group" aria-labelledby={`${id}-properties`} className="flex flex-wrap gap-1.5">
              {properties.map((property) => {
                const on = shown.has(property.id);
                return (
                  <Toggle
                    key={property.id}
                    pressed={on}
                    onPressedChange={(next) => toggleProperty(property.id, next)}
                    className={cn(
                      "h-7 min-w-0 gap-1 rounded-full border px-2.5 text-[0.8125rem]",
                      "border-dashed border-border bg-transparent text-muted-foreground",
                      "data-[state=on]:border-solid data-[state=on]:border-border data-[state=on]:bg-muted data-[state=on]:text-foreground",
                    )}
                  >
                    {on ? <IconCheck size={12} strokeWidth={2.5} /> : null}
                    {property.label}
                  </Toggle>
                );
              })}
            </div>
          </Section>
        </div>
      </div>

      {/* Kept in the page when empty: a live region that appears together with its message is often never read. */}
      <p role="status" aria-live="polite" className="sr-only">
        {said}
      </p>
    </div>
  );
}

/**
 * The shape of a display setting and the small decisions behind
 * DisplayOptionsPopover, as plain types and functions: they hold no state, so
 * a Server Component can use them too.
 */
import type { ReactNode } from "react";

/** One way to lay the list out: a list, a board, a table. */
export interface DisplayLayout {
  /** A stable identity from your own data: "board". It is what `value.layout` holds. Unique in the list. */
  id: string;
  /** What people call it: "Board". It sits under the icon. */
  label: string;
  /** An icon element for the tile, drawn at 20px. Left out, a drawing is chosen from the id (list, board, table, grid, calendar), and a layout icon stands in for any other. */
  icon?: ReactNode;
}

/** One thing the list can be grouped or ordered by. */
export interface DisplayField {
  /** A stable identity from your own data: "status". Unique in the list. */
  id: string;
  /** What people call it: "Status". Include an entry that means none, such as "No grouping", when grouping is optional. */
  label: string;
}

/** One field of a row that can be shown or hidden. */
export interface DisplayProperty {
  /** A stable identity from your own data: "assignee". Unique in the list. */
  id: string;
  /** What people call it: "Assignee". */
  label: string;
  /** Whether it shows in the defaults. Default true. */
  visible?: boolean;
}

export type DisplayDirection = "asc" | "desc";

/** What is chosen, as plain data you can keep in a saved view or in the address. */
export interface DisplayValue {
  /** The `id` of the layout. */
  layout: string;
  /** The `id` of the field the rows are grouped by. */
  grouping: string;
  /** The `id` of the field the rows are ordered by. */
  ordering: string;
  /** Which way the ordering runs. */
  direction: DisplayDirection;
  /** The `id` of every property that shows on a row, in the order the properties were given. */
  properties: readonly string[];
}

/** The four settings a person can have changed from the defaults. */
export type DisplaySection = "layout" | "grouping" | "ordering" | "properties";

/** The options a value is read against. */
export interface DisplayOptions {
  layouts: readonly DisplayLayout[];
  groupings: readonly DisplayField[];
  orderings: readonly DisplayField[];
  properties: readonly DisplayProperty[];
}

/** The words the popover says, for translation. `{count}` is filled in. */
export interface DisplayOptionsLabels {
  /** The button's text. Default "Display". */
  trigger?: string;
  /** Said after the button's name when something differs from the defaults. Default "{count} changed". */
  changed?: string;
  /** The title of the panel. Default "Display". */
  title?: string;
  /** Puts everything back. Default "Reset". */
  reset?: string;
  /** Shown beside Reset, and said politely, once it was pressed. Default "Back to the defaults". */
  resetDone?: string;
  /** The heading of the layout tiles. Default "Layout". */
  layout?: string;
  /** The heading of the grouping field. Default "Grouping". */
  grouping?: string;
  /** The heading of the ordering field. Default "Ordering". */
  ordering?: string;
  /** The name of the direction button. Default "Descending order". */
  descending?: string;
  /** The heading of the property chips. Default "Properties". */
  properties?: string;
  /** The line under it. Default "Shown on every row". */
  propertiesHint?: string;
  /** A tag beside a heading whose setting differs from the defaults. Default "Changed". */
  changedTag?: string;
}

export const DEFAULT_LABELS = {
  trigger: "Display",
  changed: "{count} changed",
  title: "Display",
  reset: "Reset",
  resetDone: "Back to the defaults",
  layout: "Layout",
  grouping: "Grouping",
  ordering: "Ordering",
  descending: "Descending order",
  properties: "Properties",
  propertiesHint: "Shown on every row",
  changedTag: "Changed",
} satisfies Required<DisplayOptionsLabels>;

/** Puts values into a template: `fill("{count} changed", { count: 2 })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? String(values[key]) : match));
}

/** What a view starts as: the first layout, grouping and ordering, ascending, and every property that is not marked hidden. */
export function defaultDisplay(options: DisplayOptions): DisplayValue {
  return {
    layout: options.layouts[0]?.id ?? "",
    grouping: options.groupings[0]?.id ?? "",
    ordering: options.orderings[0]?.id ?? "",
    direction: "asc",
    properties: options.properties.filter((property) => property.visible !== false).map((property) => property.id),
  };
}

/**
 * A value that can be drawn: an id that no longer exists falls back to the default, and the properties are the ones that
 * exist, in the order they were given, so a saved view from an older version never breaks the panel.
 */
export function readDisplay(value: DisplayValue | undefined, options: DisplayOptions, defaults: DisplayValue): DisplayValue {
  if (!value) return defaults;
  const known = (list: readonly { id: string }[], id: string, fallback: string) => (list.some((item) => item.id === id) ? id : fallback);
  const shown = new Set(value.properties);
  return {
    layout: known(options.layouts, value.layout, defaults.layout),
    grouping: known(options.groupings, value.grouping, defaults.grouping),
    ordering: known(options.orderings, value.ordering, defaults.ordering),
    direction: value.direction === "desc" ? "desc" : "asc",
    properties: options.properties.filter((property) => shown.has(property.id)).map((property) => property.id),
  };
}

/** Whether two lists hold the same ids, whatever their order. */
function sameSet(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((item) => b.includes(item));
}

/** Which of the four settings differ from the defaults. Ordering counts once, whether the field or the direction moved. */
export function changedSections(value: DisplayValue, defaults: DisplayValue): DisplaySection[] {
  const changed: DisplaySection[] = [];
  if (value.layout !== defaults.layout) changed.push("layout");
  if (value.grouping !== defaults.grouping) changed.push("grouping");
  if (value.ordering !== defaults.ordering || value.direction !== defaults.direction) changed.push("ordering");
  if (!sameSet(value.properties, defaults.properties)) changed.push("properties");
  return changed;
}
